(43811, 'Esther 4:5', 'Esther', 4, 5, 'نو هغې هتاک چې د ماڼۍ د خصیانو څخه ؤ او د پاچا له خوا د هغې د خدمت دپاره ټاکل شوی ؤ، راوغوښت او ورته ویې ویل چې مردخای ته ورشي او دا معلومه کړي چې څه پېښ شوي دي او ولې داسې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_5.mp3', '', 1761754199, 1761754199),
(43812, 'Esther 4:6', 'Esther', 4, 6, 'نو هتاک د ښار هغه چوک ته چې د ماڼۍ دروازې ته مخامخ ؤ، مردخای ته ورغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_6.mp3', '', 1761754199, 1761754199),
(43813, 'Esther 4:7', 'Esther', 4, 7, 'مردخای هغه د هرڅه څخه چې ورسره شوي وو او د هغو پیسو د پوره اندازې نه یې هم خبر کړ چې هامان د یهودیانو د وژلو دپاره وعده کړې وه چې په شاهي خزانه کې به یې اچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_7.mp3', '', 1761754199, 1761754199),
(43814, 'Esther 4:8', 'Esther', 4, 8, 'همدارنګه مردخای د هغه فرمان د متن یو نقل چې د هغوی د وژلو دپاره په شوش کې جاري شوی ؤ، هم هغه ته ورکړ چې استر ته یې وښایي او هغه خبره کړي. هغه ته یې وویل چې استر وهڅوي چې د پاچا حضور ته ورشي او د خپل قوم دپاره د هغه څخه رحم وغواړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_8.mp3', '', 1761754199, 1761754199),
(43815, 'Esther 4:9', 'Esther', 4, 9, 'هتاک بېرته لاړ او د مردخای خبره یې استر ته ورسوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_9.mp3', '', 1761754199, 1761754199),
(43816, 'Esther 4:10', 'Esther', 4, 10, 'استر دغه پیغام ورکړ چې بېرته یې مردخای ته یوسي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_10.mp3', '', 1761754199, 1761754199),
(43817, 'Esther 4:11', 'Esther', 4, 11, '«د پاچا ټول درباریان او د شاهي ولایتونو خلک پوهیږي چې د هرچا دپاره، که ښځه وي یا نر چې پرته د پاچا د بلنې دننه د پاچا دربار ته ورشي، یو حکم دا دی چې هغه به ووژل شي. خو یوازې دا چې پاچا خپله د سرو زرو امسا د هغه خواته وراوږده کړي او د هغه ژوند وژغوري. خو دېرش ورځې کیږي چې پاچا زه غوښتلې نه یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_11.mp3', '', 1761754199, 1761754199),
(43818, 'Esther 4:12', 'Esther', 4, 12, 'کله چې مردخای د استر پیغام تر لاسه کړ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_12.mp3', '', 1761754199, 1761754199),
(43819, 'Esther 4:13', 'Esther', 4, 13, 'هغه بېرته دغه ځواب واستاوه: «فکر مه کوه چې ته د پاچا په ماڼۍ کې یې، نو د ټولو یهودیانو د جملې څخه به یوازې ته خلاصون ومومې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_13.mp3', '', 1761754199, 1761754199),
(43820, 'Esther 4:14', 'Esther', 4, 14, 'که چېرې ته په دې وخت کې غلې پاتې شې، نو د یهودیانو دپاره به د بل ځای څخه مرسته او خلاصون راپیدا شي. خو ته او ستا د پلار کورنۍ به ووژل شئ. څوک څه پوهیږي، کېدای شي چې ته د همداسې وخت دپاره ملکه شوې یې!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_14.mp3', '', 1761754199, 1761754199),
(43821, 'Esther 4:15', 'Esther', 4, 15, 'نو استر مردخای ته دا ځواب واستاوه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_15.mp3', '', 1761754199, 1761754199),
(43822, 'Esther 4:16', 'Esther', 4, 16, '«لاړ شه او ټول یهودیان په شوش کې سره راټول کړه، ټول دې زما دپاره روژه ونیسي. درې شپې او درې ورځې مه څه خورئ او مه څه څښئ. زه او زما وینځې به هم ستاسو په شان روژه ونیسو. له هغې وروسته به زه پاچا ته ورشم که څه هم دا د قانون څخه سرغړونه ده. که چېرې زه د دې کار په خاطر مړه کېږم، نو مړه دې شم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_16.mp3', '', 1761754199, 1761754199),
(43823, 'Esther 4:17', 'Esther', 4, 17, 'نو مردخای لاړ او هرڅه چې استر ورته امر کړی ؤ، هماغسې یې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther4_verse_17.mp3', '', 1761754199, 1761754199),
(43824, 'Isaiah 42:1', 'Isaiah', 42, 1, 'څښتن وایي: «دا دی زما خدمتګار چې زه یې ملاتړ کومه هغه ما دی غوره کړی، زه خوشحاله یم له هغه نه ما خپل روح دی نازل کړی په هغه باندې او راولي به هغه عدالت او انصاف د نړۍ قومو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_1.mp3', '', 1761754199, 1761754199),
(43825, 'Isaiah 42:2', 'Isaiah', 42, 2, 'هغه به ونه وهي چیغې، نه لوړوي به خپل اواز اورېدل کیږي به نه د هغه اواز کوڅو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_2.mp3', '', 1761754199, 1761754199),
(43826, 'Isaiah 42:3', 'Isaiah', 42, 3, 'نه ماتوي به هغه یوه کږه لوخه هم نه مړه کوي به هغه نیمګړې بله ډېوه په حقیقت کې راولي به عدالت هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_3.mp3', '', 1761754199, 1761754199),
(43827, 'Isaiah 42:4', 'Isaiah', 42, 4, 'هغه به نه شي ناامیده او بې حوصلې ترڅو ټینګ کړي په نړۍ کې عدالت خلک د لېرې هېوادونو منتظر دي چې تعلیم د هغه واوري»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_4.mp3', '', 1761754199, 1761754199),
(43828, 'Isaiah 42:5', 'Isaiah', 42, 5, 'خدای یعنې څښتن پیدا او خپاره کړل اسمانونه هغه جوړه کړله ځمکه او پیدا یې ټول مخلوق کړ ټولو خلکو ته یې ساه او ژوندون ورکړ هغه اوس خپل خدمتګار ته داسې وایي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_5.mp3', '', 1761754199, 1761754199),
(43829, 'Isaiah 42:6', 'Isaiah', 42, 6, '«ما، څښتن راوغوښتلې ته ترڅو ټینګ کړې په نړۍ کې عدالت تاته مې درکړلو واک او ته مې وساتلې کومه لوظ زه ستا په وسیله د نړۍ د ټولو خلکو سره زه به جوړه کړمه تا نه رڼا چې د قومونو لارښوونه وکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_6.mp3', '', 1761754199, 1761754199),
(43830, 'Isaiah 42:7', 'Isaiah', 42, 7, 'ته به بینا کړې ړندې سترګې ته به ازاد کړې بندیان چې په زندان او په تیارو کې دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_7.mp3', '', 1761754199, 1761754199),
(43831, 'Isaiah 42:8', 'Isaiah', 42, 8, 'زه یم څښتن! دا دی نوم زما زه به ورنه کړم خپل جلال هېچا ته زه به هېڅکله شریک نه کړم بتان خپلې ثنا او صفت کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_8.mp3', '', 1761754199, 1761754199),
(43832, 'Isaiah 42:9', 'Isaiah', 42, 9, 'ګورئ، څه چې ما کړې پېشګویي وه عملي شول هغه ټول اوس نوې پېښې، مخکې له دې نه چې شي پېښې درکوم تاسو ته خبر»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_9.mp3', '', 1761754199, 1761754199),
(43833, 'Isaiah 42:10', 'Isaiah', 42, 10, 'څښتن ته ووایئ نوې سندره ای ټولې نړۍ، د هغه ثنا او صفت ووایئ! ای په بحیره کې مسافرو، ای په بحیره کې ټول مخلوقه ای لېرې هېوادونو او په هغو کې اوسېدونکو خلکو د هغه ثنا او صفت ووایئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_10.mp3', '', 1761754199, 1761754199),
(43834, 'Isaiah 42:11', 'Isaiah', 42, 11, 'په لوړ اواز دې د څښتن ثنا او صفت ووایي دښته او د هغې ښارګوټي کلیوال دې د قیدار همداسې وکړي د سالع ښاریان دې ووایي د خوشحالۍ سندرې هغوی دې ووهي نارې د غرونو له سرونو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_11.mp3', '', 1761754199, 1761754199),
(43835, 'Isaiah 42:12', 'Isaiah', 42, 12, 'چې په لېرې هېوادونو کې اوسیږي کوم خلک هغوی دې ووایي ثنا او صفت د څښتن او بیان دې کړي جلال د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_12.mp3', '', 1761754199, 1761754199),
(43836, 'Isaiah 42:13', 'Isaiah', 42, 13, 'څښتن جګړې ته ځي د جنګیالي په شان او په غیرت تیاروي ورته خپل ځان ورکوي هغه په چیغه د جګړې اعلان او ښکاره کوي خپل دښمنانو ته خپل زور او ځواک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_13.mp3', '', 1761754199, 1761754199),
(43837, 'Isaiah 42:14', 'Isaiah', 42, 14, 'څښتن وایي: «له ډېره وخته وم زه غلی او کنترول مې کړ خپل قهر خو اوس زه یم د داسې ښځې په شان چې کوي زګېروي له ډېره درده د لنګون په وخت کې او نفس یې سوځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_14.mp3', '', 1761754199, 1761754199),
(43838, 'Isaiah 42:15', 'Isaiah', 42, 15, 'زه به له منځه یوسم غونډۍ او غرونه زه به وچ کړمه واښه او ونې وچ به سیندونه کړمه په کې ښکاره چې جزیرې شي بیا به هم وچ کړم د اوبو ډنډونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_15.mp3', '', 1761754199, 1761754199),
(43839, 'Isaiah 42:16', 'Isaiah', 42, 16, 'زه به ړندو ته لارښوونه وکړم په هغو لارو چې هېڅ وخت ورباندې تللي نه وي زه به بدله په رڼا کړمه تيارې د دوی او ورته هوارې به کړم کنډې او کپرې ځمکې زه به هغوی ته دا کارونه وکړم هغوی به هېڅکله پرېنږدمه یوازې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_16.mp3', '', 1761754199, 1761754199),
(43840, 'Isaiah 42:17', 'Isaiah', 42, 17, 'خو هغه څوک چې باور لري بتانو باندې او ورته وایي خپل خدایان هغوی به سپک شي او ډېر به وشرمیږي»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_17.mp3', '', 1761754199, 1761754199),
(43841, 'Isaiah 42:18', 'Isaiah', 42, 18, 'څښتن وایي: «ای کڼو خلکو واورئ! ای ړندو خلکو، خلاصې کړئ سترګې او وګورئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_18.mp3', '', 1761754199, 1761754199),
(43842, 'Isaiah 42:19', 'Isaiah', 42, 19, 'څوک دی ړوند زما د خادم په شان؟ څوک دی کوڼ زما د استازي په شان؟ څوک دی ړوند زما، څښتن د ټاکلي خادم په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_19.mp3', '', 1761754199, 1761754199),
(43843, 'Isaiah 42:20', 'Isaiah', 42, 20, 'ډېر شیان ولیدل تاسو خو اهمیت مو ورته ورنه کړ غوږونه خلاص دي ستاسو خو څه پرې نه اورئ»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_20.mp3', '', 1761754199, 1761754199),
(43844, 'Isaiah 42:21', 'Isaiah', 42, 21, 'دا چې څښتن عادل دی، هغه لېوال ؤ چې قوانین یې پرتمین وګڼل شي او درناوی یې وشي او جلالي ښکاره شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_21.mp3', '', 1761754199, 1761754199),
(43845, 'Isaiah 42:22', 'Isaiah', 42, 22, 'خو اوس دا خلک لوټ شوي دي په کندو کې راګېر او اچول شوي زندانونو ته د خلاصون دپاره یې رانغی هېڅوک دي تالا شوي او چور شوي دا خلک خو څوک نه ؤ چې ووایي: «بېرته ولېږئ هغوی»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_22.mp3', '', 1761754199, 1761754199),
(43846, 'Isaiah 42:23', 'Isaiah', 42, 23, 'ایا څوک شته تاسو کې چې دې خبرو ته ونیسي غوږ؟ ایا دې ته به پام وکړي څوک راتلونکي وخت کې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_23.mp3', '', 1761754199, 1761754199),
(43847, 'Isaiah 42:24', 'Isaiah', 42, 24, 'چا اجازه ورکړه چې شي تالا دې یعقوب؟ لوټمارانو ته تسلیم کړ اسراییل چا؟ څښتن خپله داسې وکړل ځکه چې مونږه ګناه وکړه د هغه په وړاندې قدم وانخیست اسراییلو د هغه په لاره ویې نه کړه پیروي د هغه له قوانینو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_24.mp3', '', 1761754199, 1761754199),
(43848, 'Isaiah 42:25', 'Isaiah', 42, 25, 'له دې امله څښتن نازل کړ خپل غضب په هغوی او هغوی ولیده کړاو او تاوان د جګړې بلېده د هغه قهر اسراییلو کې لکه د اور په شان خو پوه نه شول هغوی چې څه کیږي هغوی وانخیست هېڅ عبرت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah42_verse_25.mp3', '', 1761754199, 1761754199),
(43849, 'Job 27:1', 'Job', 27, 1, 'ايُوب خپله خبره جارى وساتله،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_1.mp3', '', 1761754199, 1761754199),
(43850, 'Job 27:2', 'Job', 27, 2, '”زۀ په ژوندى خُدائ پاک قسم خورم، چا چې زما حقُونه اخستى دى، او هغه قادر خُدائ چا چې زما ژوند تريخ کړے دے،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_2.mp3', '', 1761754199, 1761754199),
(43851, 'Job 27:3', 'Job', 27, 3, 'چې ترڅو پورې زۀ ژوندے يم او چې د خُدائ پاک روح په ما کښې وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_3.mp3', '', 1761754199, 1761754199),
(43852, 'Job 27:4', 'Job', 27, 4, 'نو زما ژبه به غلطې خبرې ونۀ کړى، او زما ژبه به دروغ ونۀ وائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_4.mp3', '', 1761754199, 1761754199),
(43853, 'Job 27:5', 'Job', 27, 5, 'زۀ به هيڅکله دا ونۀ وايم چې تۀ په حقه يې، ترڅو پورې چې مړ شوے نۀ يم نو صداقت به ما کښې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_5.mp3', '', 1761754199, 1761754199),
(43854, 'Job 27:6', 'Job', 27, 6, 'زۀ به دا دعوىٰ هيڅکله پرې نۀ ږدم چې زۀ بې‌ګناه يم، ځکه چې ټول عُمر زما ضمير صفا دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_6.mp3', '', 1761754199, 1761754199),
(43855, 'Job 27:7', 'Job', 27, 7, 'څوک چې زما مخالفت کوى يا ما سره جګړې کوى نو هغوئ ته دې د ګناهګارو او بدعملو په شان سزا مِلاو شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_7.mp3', '', 1761754199, 1761754199),
(43856, 'Job 27:8', 'Job', 27, 8, 'ځکه چې د خُدائ نه د منکرو خلقو اُميد به څۀ وى چې کله هغوئ د ژوند نه لاس ووينځى، کله چې خُدائ پاک د هغوئ نه ژوند واخلى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_8.mp3', '', 1761754199, 1761754199),
(43857, 'Job 27:9', 'Job', 27, 9, 'چې کله مصيبت په هغوئ باندې راشى نو خُدائ پاک به د هغوئ ژړا اورى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_9.mp3', '', 1761754199, 1761754199),
(43858, 'Job 27:10', 'Job', 27, 10, 'هغوئ به د قادر خُدائ سره خوشحاله شى څۀ؟ هغوئ به هر وخت خُدائ پاک ته آواز کولے شى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_10.mp3', '', 1761754199, 1761754199),
(43859, 'Job 27:11', 'Job', 27, 11, 'زۀ به تا ته د خُدائ پاک د طاقت په حقله ښودنه وکړم، څۀ چې د قادر خُدائ سره وى نو زۀ به هغه نۀ پټوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_11.mp3', '', 1761754199, 1761754199),
(43860, 'Job 27:12', 'Job', 27, 12, 'تاسو دا هر څۀ په خپله ليدلى دى، خو بيا هم تاسو ما ته دا فضول خبرې کوئ؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_12.mp3', '', 1761754199, 1761754199),
(43861, 'Job 27:13', 'Job', 27, 13, '”دا د خُدائ پاک سره د بدعمله کسانو برخه ده، او دا هغه ميراث دے چې ظالمانو ته د قادر خُدائ د طرف نه ملاويږى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_13.mp3', '', 1761754199, 1761754199),
(43862, 'Job 27:14', 'Job', 27, 14, 'کۀ د هغوئ اولاد ډېر هم وى، خو د هغوئ بچى به په جنګ کښې او د لوږې نه مړۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_14.mp3', '', 1761754199, 1761754199),
(43863, 'Job 27:15', 'Job', 27, 15, 'څوک چې پاتې وى نو هغوئ به په وبا مړۀ شى، او د هغوئ کونډې به هم په هغوئ باندې ژړا ونۀ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_15.mp3', '', 1761754199, 1761754199),
(43864, 'Job 27:16', 'Job', 27, 16, 'هغوئ سره سپين زر د خاورو نه زيات دى، او بې‌حسابه جامې ورسره دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_16.mp3', '', 1761754199, 1761754199),
(43865, 'Job 27:17', 'Job', 27, 17, 'هغوئ به دا رايوځائ کړى، خو نېکان به دا واغوندى، او بې‌ګناه کسان به سپين زر په خپلو کښې تقسيم کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_17.mp3', '', 1761754199, 1761754199),
(43866, 'Job 27:18', 'Job', 27, 18, 'بدعمله کسان خپل کورونه د جالو په شان داسې کمزورى جوړوى، لکه چې څوکيداران څپر جوړوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_18.mp3', '', 1761754199, 1761754199),
(43867, 'Job 27:19', 'Job', 27, 19, 'هغوئ به د دولت سره څملى، خو چې سترګې وغړوى، نو مال به يې ختم وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_19.mp3', '', 1761754199, 1761754199),
(43868, 'Job 27:20', 'Job', 27, 20, 'يره د سېلاب په شان په هغوئ باندې غالبه شى، او د شپې طوفان يې يوسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_20.mp3', '', 1761754199, 1761754199),
(43869, 'Job 27:21', 'Job', 27, 21, 'د نمرخاتۀ طرف هوا هغوئ اوچت کړى او هغوئ ختم شى، او دا هوا يې په مخه يوسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_21.mp3', '', 1761754199, 1761754199),
(43870, 'Job 27:22', 'Job', 27, 22, 'دا په بې‌رحمۍ سره په هغوئ باندې راوغورزيږى، اګر چې هغوئ د تښتېدو پوره کوشش کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_22.mp3', '', 1761754199, 1761754199),
(43871, 'Job 27:23', 'Job', 27, 23, 'هوا په هغوئ پسې داسې شور جوړوى لکه چې سړے په چا پورې خندا کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job27_verse_23.mp3', '', 1761754199, 1761754199),
(43872, 'Psalms 114:1', 'Psalms', 114, 1, 'کله چې ووتل د مصر نه د اسراییلو خلک هغه پردی وطن چې کله پرېښودلو د یعقوب اولادې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms114_verse_1.mp3', '', 1761754199, 1761754199),
(43873, 'Psalms 114:2', 'Psalms', 114, 2, 'یهودا شو د څښتن سپېڅلی ځای اسراییل شو د هغه د پاچاهۍ ځای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms114_verse_2.mp3', '', 1761754199, 1761754199),
(43874, 'Psalms 114:3', 'Psalms', 114, 3, 'خدای چې کله راښکاره شو سرې بحیرې ته نو بحیره وچه شوه د اردن سیند هم ودرېده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms114_verse_3.mp3', '', 1761754199, 1761754199),
(43875, 'Psalms 114:4', 'Psalms', 114, 4, 'شول په ټوپونو غرونه لکه پسونو په شان وهل خېزونه غونډۍ ګانو لکه د وریو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms114_verse_4.mp3', '', 1761754199, 1761754199),
(43876, 'Psalms 114:5', 'Psalms', 114, 5, 'ای دریابه په تا څه وشول چې وچ شوې؟ د اردن سینده ولې ودرېدلې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms114_verse_5.mp3', '', 1761754199, 1761754199),
(43877, 'Psalms 114:6', 'Psalms', 114, 6, 'ای غرونو، ولې مو ووهل ټوپونه د پسونو په شان؟ ای غونډیو، ولې مو ووهل خېزونه لکه وریو په شان؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms114_verse_6.mp3', '', 1761754199, 1761754199),
(43878, 'Psalms 114:7', 'Psalms', 114, 7, 'د څښتن په حضور کې ای ځمکې په لړزان شه د یعقوب د خدای حضور کې په لړزان شه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms114_verse_7.mp3', '', 1761754199, 1761754199),
(43879, 'Psalms 114:8', 'Psalms', 114, 8, 'هغه بدل کړ ګټ په ډنډ باندې او کلکه تیږه په چینې باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms114_verse_8.mp3', '', 1761754199, 1761754199),
(43880, 'Psalms 123:1', 'Psalms', 123, 1, 'سترګې مې ستا په لور نیولې دي څښتنه تاته چې تخت دې په اسمان کې دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms123_verse_1.mp3', '', 1761754199, 1761754199),
(43881, 'Psalms 123:2', 'Psalms', 123, 2, 'مونږه سترګې دي نیولې ای زمونږه څښتن خدایه لکه نوکر چې وي نیولې سترګې خپل بادار ته لکه چې وینځې وي نیولې سترګې خپلې بادارې ته ترڅو په مونږ باندې ته رحم وکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms123_verse_2.mp3', '', 1761754199, 1761754199),
(43882, 'Psalms 123:3', 'Psalms', 123, 3, 'ای څښتنه، په مونږ ورحمېږه او په مونږه رحم وکړه ځکه چې مونږ سره دی شوی ډېر زیات سپک رفتار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms123_verse_3.mp3', '', 1761754199, 1761754199),
(43883, 'Psalms 123:4', 'Psalms', 123, 4, 'په مونږ ملنډې وهل شوې ډېرې زیاتې د شتمنو له خوا او مونږ زغملی ډېر سپکاوی دی د مغرورانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms123_verse_4.mp3', '', 1761754199, 1761754199),
(43884, 'Ezra 8:1', 'Ezra', 8, 1, 'دا د هغو طایفو د مشرانو لست دی چې په بابل کې جلاوطني وو او د ارتخششتا د امپراتورۍ په وخت کې زما سره اورشلیم ته راستانه شول:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_1.mp3', '', 1761754199, 1761754199),
(43885, 'Ezra 8:4', 'Ezra', 8, 4, 'الیهوعینای د زرحیا زوی د دوو سوو تنو سره د فحت موآب له طایفې څخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_4.mp3', '', 1761754199, 1761754199),
(43886, 'Ezra 8:5', 'Ezra', 8, 5, 'شکنیا د یحزییل زوی د درېو سوو تنو سره د زتو له طایفې څخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_5.mp3', '', 1761754199, 1761754199),
(43887, 'Ezra 8:6', 'Ezra', 8, 6, 'عابد د یوناتان زوی د پنځوسو تنو سره د عادین له طایفې څخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_6.mp3', '', 1761754199, 1761754199),
(43888, 'Ezra 8:7', 'Ezra', 8, 7, 'اشعیا د عتلیا زوی د اویاو تنو سره د عیلام له طایفې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_7.mp3', '', 1761754199, 1761754199),
(43889, 'Ezra 8:8', 'Ezra', 8, 8, 'زبدیا د میکاییل زوی د اتیاو تنو سره د شفطیا له طایفې څخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_8.mp3', '', 1761754199, 1761754199),
(43890, 'Ezra 8:9', 'Ezra', 8, 9, 'عوبدیا د یحییل زوی د دوو سوو اتلسو تنو سره د یوآب له طایفې څخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_9.mp3', '', 1761754199, 1761754199),
(43891, 'Ezra 8:10', 'Ezra', 8, 10, 'شلومیت د یوسفیا زوی د یوسلو شپېتو تنو سره د باني له طایفې څخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_10.mp3', '', 1761754199, 1761754199),
(43892, 'Ezra 8:11', 'Ezra', 8, 11, 'زکریا د ببای زوی د اته ویشتو تنو سره د ببای له طایفې څخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_11.mp3', '', 1761754199, 1761754199),
(43893, 'Ezra 8:12', 'Ezra', 8, 12, 'یوحانان د هقاتان زوی د یوسلو لسو کسانو سره د عزجد له طایفې څخه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_12.mp3', '', 1761754199, 1761754199),
(43894, 'Ezra 8:13', 'Ezra', 8, 13, 'الیفلط، یوییل، شمعیه د شپېتو کسانو سره د ادونیقام له طایفې څخه. دوی وروسته راستانه شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_13.mp3', '', 1761754199, 1761754199),
(43895, 'Ezra 8:14', 'Ezra', 8, 14, 'عوتای او ذکور د اویاو کسانو سره د بغوای له طایفې څخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_14.mp3', '', 1761754199, 1761754199),
(43896, 'Ezra 8:15', 'Ezra', 8, 15, 'ما هغوی د هغه نهر په غاړه چې د اهاوا د ښارګوټي خواته بهیږي، سره راټول کړل او درې ورځې مو هلته خپلې خېمې ودرولې. کله چې ما هغه خلک او کاهنان وکتل، د هغوی په منځ کې مې د لاویانو څخه څوک پیدا نه کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_15.mp3', '', 1761754199, 1761754199),
(43897, 'Ezra 8:16', 'Ezra', 8, 16, 'ما دغه مشران راوغوښتل چې نومونه یې دا دي: الیعازر، ارییل، شمعیه، الناتان، یاریب، الناتان، ناتان، زکریا او مشلام. همدارنګه مې دوه ښوونکي، یویاریب او الناتان هم راوغوښتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_16.mp3', '', 1761754199, 1761754199),
(43898, 'Ezra 8:17', 'Ezra', 8, 17, 'ما هغوی عیدو ته چې په کاسیفیا کې مشر ؤ، ولېږل او هغوی ته مې وویل چې د هغه او د هغه د ملګرو څخه چې د خدای د کور خدمتګاران وو، وغواړي چې مونږ ته داسې خلک راولېږي چې زمونږ د خدای په کور کې خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_17.mp3', '', 1761754199, 1761754199),
(43899, 'Ezra 8:18', 'Ezra', 8, 18, 'خدای په مونږ باندې فضل وکړ او هغوی د شربیا په نوم یو لایق سړی چې لاوي ؤ او د محلي د طایفې څخه ؤ، د خپلو اتلسو زامنو او خپلوانو سره مونږ ته راولېږه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_18.mp3', '', 1761754199, 1761754199),
(43900, 'Ezra 8:19', 'Ezra', 8, 19, 'همدارنګه هغوی حشبیا او اشعیا چې د مراري د طایفې څخه وو، د خپلو شلو خپلوانو او د هغوی د زامنو سره راولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_19.mp3', '', 1761754199, 1761754199),
(43901, 'Ezra 8:20', 'Ezra', 8, 20, 'برسېره پردې هغوی د خدای د کور دوه سوه شل تنه هغه خدمتګاران چې د هغوی نیکونه د داود پاچا او د هغه د درباریانو له خوا د لاویانو سره د مرستې دپاره ټاکل شوي وو، راولېږل. د هغوی ټولو نومونه په لست کې لیکل شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_20.mp3', '', 1761754199, 1761754199),
(43902, 'Ezra 8:21', 'Ezra', 8, 21, 'هلته ما د اهاوا د نهر په غاړه د ټولو نه وغوښتل چې روژه ونیسو او د خپل خدای په مخکې خپل ځانونه عاجز کړو او د هغه څخه وغواړو چې مونږ ته په خپل سفر کې لارښوونه وکړي او زمونږ، زمونږ د اولادونو او زمونږ د ټولې شتمنۍ څخه ساتنه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_21.mp3', '', 1761754199, 1761754199),
(43903, 'Ezra 8:22', 'Ezra', 8, 22, 'دا به زما دپاره د شرم خبره وای چې د پاچا څخه مې د سپرو عسکرو لښکر غوښتلی وای، ترڅو په سفر کې مونږ د دښمنانو څخه خوندي وساتي، ځکه چې مونږ هغه ته ویلي وو چې هغه څوک چې زمونږ په خدای باندې توکل کوي، نو هغه ورته برکت ورکوي، خو څوک چې د هغه نه مخ اړوي، په هغه باندې په قهر کیږي او سزا ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_22.mp3', '', 1761754199, 1761754199),
(43904, 'Ezra 8:23', 'Ezra', 8, 23, 'نو مونږ روژه ونیوله او خدای ته مو زاري وکړه چې مونږ وساتي او هغه زمونږ دعا قبوله کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_23.mp3', '', 1761754199, 1761754199),
(43905, 'Ezra 8:24', 'Ezra', 8, 24, 'د کاهنانو د مشرانو څخه ما دولس تنه غوره کړل، یعنې شربیا، حشبیا او لس تنه د هغوی د خپلوانو څخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_24.mp3', '', 1761754199, 1761754199),
(43906, 'Ezra 8:25', 'Ezra', 8, 25, 'بیا هغه سپین زر، سره زر او لوښي چې پاچا، د هغه مشاورانو او درباریانو او د اسراییلو حاضرو خلکو زمونږ د خدای د کور دپاره ورکړي وو، ما هغه وتلل او کاهنانو ته مې ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_25.mp3', '', 1761754199, 1761754199),
(43907, 'Ezra 8:28', 'Ezra', 8, 28, 'ما کاهنانو ته وویل: «تاسو د خپلو نیکونو څښتن خدای ته سپېڅلي یئ او دا لوښي هم هغه ته سپېڅلي دي. سپین او سره زر څښتن ته رضاکارانه ورکړل شوې نذرانې دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_28.mp3', '', 1761754199, 1761754199),
(43908, 'Ezra 8:29', 'Ezra', 8, 29, 'تاسو هغه د څښتن کور ته چې په اورشلیم کې دی، په احتیاط سره یوسئ. هلته د کاهنانو په کوټو کې د کاهنانو د مشرانو، لاویانو او د اسراییلو د کورنیو د مشرانو په مخکې هغه شیان وتلئ او هغوی ته یې ورکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_29.mp3', '', 1761754199, 1761754199),
(43909, 'Ezra 8:30', 'Ezra', 8, 30, 'نو کاهنانو او لاویانو دا مسوولیت په غاړه واخیست چې هغه سپین زر، سره زر او لوښي زمونږ د خدای کور ته چې په اورشلیم کې دی، یوسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_30.mp3', '', 1761754199, 1761754199),
(43910, 'Ezra 8:31', 'Ezra', 8, 31, 'د کال د لومړۍ میاشتې په دولسمه ورځ مونږ د اهاوا د نهر څخه اورشلیم ته روان شو. زمونږ خدای زمونږ سره ؤ او په سفر کې یې د دښمنانو د کمین او حملې څخه وساتلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezra8_verse_31.mp3', '', 1761754199, 1761754199);